target.css:
:root {
  --ink: #263a4a;
  --paper: #fffdf8;
  --line: #d8e0e4;
  --sky: #dff2f6;
  --coral: #e96b5a;
}

.pickup-slip {
  box-sizing: border-box;
  width: 460px;
  padding: 16px;
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 14px;
}

.slip-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding-bottom: 12px;
  border-bottom: 1px solid var(--line);
}

.camera {
  display: grid;
  width: 42px;
  height: 42px;
  place-items: center;
  background: var(--sky);
  border-radius: 10px;
  font-size: 22px;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--coral);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
}

h1 {
  margin: 0;
  color: var(--ink);
  font-size: 20px;
  line-height: 1.1;
}

.collection-details {
  display: flex;
  gap: 42px;
  padding: 14px 0;
}

.collection-details p {
  margin: 0;
  color: var(--ink);
  font-size: 14px;
}

.collection-details span,
.collection-details strong {
  display: block;
}

.collection-details span {
  margin-bottom: 3px;
  color: var(--coral);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.06em;
}

.slip-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: var(--ink);
  font-size: 12px;
}

.slip-footer b {
  padding: 5px 9px;
  background: var(--coral);
  border-radius: 999px;
  color: var(--paper);
  font-size: 10px;
  letter-spacing: 0.08em;
}

